    --ds-color-static-red-0: #fce8e8;
    --ds-color-gradient-content-fade-left: linear-gradient(90deg, hsla(0, 0%, 100%, 0), #000);
    --ds-color-gradient-content-fade-right: linear-gradient(-90deg, hsla(0, 0%, 100%, 0), #fff);
    --ds-color-gradient-content-fade-up: linear-gradient(180deg, hsla(0, 0%, 100%, 0), #fff);
    --ds-color-gradient-content-fade-down: linear-gradient(0deg, hsla(0, 0%, 100%, 0), #fff);
}
}
